import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { confirmReturnReceiveWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await confirmReturnReceiveWorkflow(req.scope)
    .run({
      input: {
        return_id: "return_123",
      }
    })

  res.send(result)
}

